def test_conversion_rate_includes_none_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_dedupe_keeps_last_duplicate_then_sorts():
    events = parse_session_log(["a,3,1", "b,2,1", "a,2,0", "z,1,"])
    assert dedupe_sessions(events) == [events[3], events[2], events[1]]


def test_parse_whitespace_comments_and_flags():
    lines = ["", " \t", " # comment", " x , 4 , 0 ", " y , 5 , "]
    assert parse_session_log(lines) == [
        {"id": "x", "day": 4, "converted": False},
        {"id": "y", "day": 5, "converted": None},
    ]


@pytest.mark.parametrize("bad", ["x,1", "x,1,0,1", "x,today,1"])
def test_parse_errors_count_skipped_lines(bad):
