def test_daily_counts_and_window_boundaries():
    events = parse_session_log(["a,0,1", "b,2,1", "c,2,1", "d,3,0", "e,5,1"])
    counts = daily_conversion_counts(events, 1, 4)
    assert counts == [0, 2, 0, 0]
    assert daily_conversion_counts(events, 3, 2) == []
    assert conversions_in_window(counts, 0) == 0
    assert conversions_in_window(counts, 2) == 0
    assert conversions_in_window(counts, 10) == 2


def test_summary_pools_sessions_and_uses_calendar_days():
    groups = {"a": parse_session_log(["a,1,1"]), "b": parse_session_log(["b,1,1", "c,4,0"]), "c": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


